920	// validateEnvelope re-checks every invariant on load so a tampered or
921	// hand-edited file cannot bypass the domain rules.
922	func validateEnvelope(env envelope) error {
923		seenCircuit := make(map[[2]string]bool)
924		circuitOK := make(map[[2]string]bool)
925		for i, c := range env.Circuits {
926			key := [2]string{c.Name, itoa(c.Version)}
927			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
928				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
929			}
930			if c.Version <= 0 {
931				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
932			}
933			if seenCircuit[key] {
934				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
935			}
936			seenCircuit[key] = true
937			if c.Constraints <= 0 {
938				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
939			}
940			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
941				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
942			}
943			// The same representability rule the write path enforces: wire 0 plus
944			// every declared input must fit inside the platform's int. A record
945			// beyond that bound can never have been written by this build and
946			// cannot be checked safely, so the directory is corrupt rather than
947			// silently narrowed or read with a wrapped-around layout.
948			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
949				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
950					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
951			}
952			if c.Definition != nil {
953				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
954					return err
955				}
956			}
957			circuitOK[key] = true
958		}
959		seenSetup := make(map[[2]string]bool)
960		for i, p := range env.Setups {
961			key := [2]string{p.Name, itoa(p.Version)}
962			if !circuitOK[key] {
963				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
964			}
965			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
966			if c == nil || !c.Frozen {
967				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
968			}
969			if seenSetup[key] {
970				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
971			}
972			seenSetup[key] = true
973		}
974		seenJob := make(map[string]bool)
975		for i, j := range env.Jobs {
976			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
977				return fmt.Errorf("job #%d has an empty or blank id", i+1)
978			}
979			if seenJob[j.ID] {
980				return fmt.Errorf("job %q appears more than once", j.ID)
981			}
982			seenJob[j.ID] = true
983			if j.Kind != "prove" {
984				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
985			}
986			if j.Attempt <= 0 {
987				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
988			}
989			key := [2]string{j.Circuit, itoa(j.Version)}
990			if !circuitOK[key] {
991				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
992			}
993			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
994			if c == nil || !c.Frozen {
995				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
996			}
997			if !seenSetup[key] {
998				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
999			}
1000			// A recorded compiled-artifact binding must still resolve against the
1001			// pinned version's artifact; a dangling or mismatched binding makes
1002			// the file unreadable rather than silently dropping the binding.
1003			if j.CompiledHash != "" {
1004				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1005				if artifact == nil {
1006					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1007				}
1008				if artifact.Hash != j.CompiledHash {
1009					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1010						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1011				}
1012			}
1013		}
1014		seenArtifact := make(map[[2]string]bool)
1015		for i, a := range env.Artifacts {
1016			key := [2]string{a.Name, itoa(a.Version)}
1017			if !circuitOK[key] {
1018				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1019			}
1020			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1021			if c == nil || !c.Frozen {
1022				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1023			}
1024			if seenArtifact[key] {
1025				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1026			}
1027			seenArtifact[key] = true
1028			if c.Definition == nil {
1029				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1030			}
1031			if a.Constraints != c.Constraints {
1032				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1033					a.Name, a.Version, a.Constraints, c.Constraints)
1034			}
1035			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1036			if err != nil {
1037				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1038			}
1039			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1040				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1041			}
1042			wantHash := artifactHash(a.Name, a.Version, def)
1043			if a.Hash != wantHash {
1044				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1045					a.Name, a.Version, a.Hash, wantHash)
1046			}
1047		}
1048		return nil
1049	}
1050	
1051	// validatePersistDefinition re-validates a stored definition against its
1052	// version's declared counts: prime modulus, in-range wires and an exact
1053	// constraint count match.
1054	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1055		parsed, err := definitionFromPersist(*def, public, private)
1056		if err != nil {
1057			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1058		}
1059		if !parsed.compatibleWith(constraints, public, private) {
1060			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1061		}
1062		return nil
1063	}
1064	
1065	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1066		for i := range cs {
1067			if cs[i].Name == name && cs[i].Version == version {
1068				return &cs[i]
1069			}
1070		}
1071		return nil
1072	}
1073	
1074	func itoa(v int) string { return fmt.Sprintf("%d", v) }
