		return exitUsage
	}
	if f.name == "" {
		fmt.Fprintln(os.Stderr, "error: --name is required for job-submit")
		return exitUsage
	}
	if f.version <= 0 {
		fmt.Fprintln(os.Stderr, "error: --version must be a positive integer for job-submit")
		return exitUsage
	}
