1	package zkcircuit
2	
3	import (
4		"errors"
5		"strconv"
6		"strings"
7		"testing"
8	)
9	
10	// Regression tests for the pinned circuit version on a committed job record.
11	// The "version" a job writes is the sole authority for which frozen circuit —
12	// and thereby which trusted setup and compiled artifact — the job belongs to.
13	// Any spelling the ordinary read would fill Version from names that one
14	// field: the canonical "version", an ASCII letter-case variant, a JSON-escaped
15	// spelling, or the Unicode-folded long-s "verſion" (U+017F). Two such
16	// spellings on one record make the version a function of key order
17	// (encoding/json keeps the last value) and are refused as data corruption —
18	// equal or differing values, both legal, and even with unrelated fields
19	// interleaved. A long-s spelling standing alone is still the single version
20	// field and keeps reading as it does today.
21	
22	// jsonBackslash is one literal backslash, written as a raw string so the
23	// uXXXX escape sequences built below keep their backslash in this source.
24	const jsonBackslash = `\`
25	
26	// jobFieldIndent is the indentation of a job record's own members as written
27	// by json.MarshalIndent with two-space indents (envelope → jobs → record).
28	const jobFieldIndent = "\n      "
29	
30	// seedTwoVersionJobStore commits two frozen, set-up versions c@1 and c@2
31	// (definitions/compile are unnecessary for an unbound job) and one unbound
32	// job pinned to v1. It reproduces the ambiguity that matters: a job spelling
33	// version both as 1 and 2 has a valid target under either value.
34	func seedTwoVersionJobStore(t *testing.T) string {
35		t.Helper()
36		dir := t.TempDir()
37		s, err := Open(dir)
38		if err != nil {
39			t.Fatal(err)
40		}
41		seedFrozenSource(t, s, "c", 1, 1, 1, 1, "")
42		seedFrozenSource(t, s, "c", 2, 1, 1, 1, "")
43		if _, err := s.SubmitJob(boundProveJob("jmv", "c", 1, "")); err != nil {
44			t.Fatal(err)
45		}
46		if err := s.Close(); err != nil {
47			t.Fatal(err)
48		}
49		return dir
50	}
51	
52	// replaceInJob scopes a literal replacement to the job object carrying id:
53	// it finds the id marker and replaces the first occurrence of old after it,
54	// so a "version": 1 shared by the circuit/setup/artifact records is never
55	// mistaken for the job's own field.
56	func replaceInJob(t *testing.T, dir, id, old, repl string) []byte {
57		t.Helper()
58		raw, err := readDataFile(t, dir)
59		if err != nil {
60			t.Fatal(err)
61		}
62		marker := `"id": "` + id + `"`
63		at := strings.Index(string(raw), marker)
64		if at < 0 {
65			t.Fatalf("committed file does not carry job marker %q", marker)
66		}
67		rel := strings.Index(string(raw[at:]), old)
68		if rel < 0 {
69			t.Fatalf("job %q does not carry %q after its id marker", id, old)
70		}
71		pos := at + rel
72		bad := string(raw[:pos]) + repl + string(raw[pos+len(old):])
73		writeDataFile(t, dir, []byte(bad))
74		return []byte(bad)
75	}
76	
77	// versionLine is the single-line form of the job's own version member, as
78	// written by the deterministic encoder.
79	func versionLine(v int) string { return `"version": ` + strconv.Itoa(v) }
80	
81	// assertJobVersionCorrupt opens dir, requires ErrDataCorrupt naming id and
82	// the version field, and checks the file is still byte-for-byte want.
83	func assertJobVersionCorrupt(t *testing.T, dir, id string, want []byte) {
84		t.Helper()
85		_, err := Open(dir)
86		if !errors.Is(err, ErrDataCorrupt) {
87			t.Fatalf("want ErrDataCorrupt, got %v", err)
88		}
89		if !strings.Contains(err.Error(), strconv.Quote(id)) {
90			t.Fatalf("error does not name the ambiguous job %q: %v", id, err)
91		}
92		if !strings.Contains(err.Error(), "version") {
93			t.Fatalf("error does not name the version field: %v", err)
94		}
95		got, rerr := readDataFile(t, dir)
96		if rerr != nil {
97			t.Fatal(rerr)
98		}
99		if string(got) != string(want) {
100			t.Fatalf("open modified the damaged file")
101		}
102	}
103	
104	// A job carrying two recognized version spellings is refused: canonical plus
105	// an ASCII case variant or a JSON-escaped spelling, equal or differing values,
106	// both values legal. The error names the job and the version field, and the
107	// file is left byte-for-byte in place.
108	func TestJobVersionDuplicateIsCorrupt(t *testing.T) {
109		escV := jsonBackslash + "u0076ersion" // "version" as raw JSON text
110		escI := "vers" + jsonBackslash + "u0069on"
111		cases := []struct {
112			name string
113			frag string // replaces the single "version": 1 line
114		}{
115			{"identical values, ASCII variant", `"version": 1, "VERSION": 1`},
116			{"differing values, ASCII variant", `"version": 1, "VERSION": 2`},
117			{"upper then canonical, differing", `"VERSION": 2, "version": 1`},
118			{"mixed case variant, same value", `"version": 1, "VeRsIoN": 1`},
119			{"escaped leading letter, same value", `"version": 1, "` + escV + `": 1`},
120			{"escaped inner letter, differing", `"version": 1, "` + escI + `": 2`},
121		}
122		for _, tc := range cases {
123			t.Run(tc.name, func(t *testing.T) {
124				dir, h := seedBoundJobStore(t)
125				bad := replaceInJob(t, dir, "j-bound", versionLine(1), tc.frag)
126	
127				assertJobVersionCorrupt(t, dir, "j-bound", bad)
128				// The committed compiled hash survives untouched: the reader must
129				// neither pick a version nor rewrite (and drop) the binding.
130				if !strings.Contains(string(bad), `"compiled_hash": "`+h+`"`) {
131					t.Fatalf("test setup lost the bound hash")
132				}
133				if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
134					t.Fatalf("reopen on ambiguous dir: want corruption, got %v", err)
135				}
136			})
137		}
138	}
139	
140	// The motivating ambiguity: an unbound job whose version is spelled both 1 and
141	// 2, with both versions frozen and set up. Without the uniqueness rule
142	// encoding/json keeps the last value and the job reads against v2; the read
143	// must instead be refused.
144	func TestJobVersionAmbiguousBetweenTwoFrozenVersions(t *testing.T) {
145		dir := seedTwoVersionJobStore(t)
146		bad := replaceInJob(t, dir, "jmv", versionLine(1), `"version": 1, "VERSION": 2`)
147		assertJobVersionCorrupt(t, dir, "jmv", bad)
148	}
149	
150	// The two version spellings need not be adjacent: a second spelling later in
151	// the record, separated by other fields, is still a duplicate and is rejected.
152	func TestJobVersionDuplicateInterspersedIsCorrupt(t *testing.T) {
153		dir, _ := seedBoundJobStore(t)
154		old := `"version": 1,` + jobFieldIndent + `"kind": "prove",` + jobFieldIndent + `"attempt": 1`
155		repl := `"version": 1,` + jobFieldIndent + `"kind": "prove",` + jobFieldIndent +
156			`"attempt": 1,` + jobFieldIndent + `"VERSION": 2`
157		bad := replaceInJob(t, dir, "j-bound", old, repl)
158		assertJobVersionCorrupt(t, dir, "j-bound", bad)
159	}
160	
161	// A long-s "verſion" beside a canonical or ASCII spelling is a duplicate
162	// version field, direct or u017f-escaped, in either order and whether the two
